  1	import { z } from "zod";
  2	import { baselineFrameBudgets, moveTimingSchema, type MoveTiming } from "../frameBudgets.js";
  3	import { formatIssues, type ValidationResult } from "../rules.js";
  4	
  5	/**
  6	 * An axis-aligned box in integer sub-pixels, relative to a fighter's origin (the middle of its feet) for a fighter
  7	 * facing right; y grows upwards from the floor. The box covers the half-open ranges [x, x + w) × [y, y + h), so it
  8	 * needs a positive width and height to cover anything.
  9	 */
 10	export const boxSchema = z.strictObject({
 11	  x: z.int(),
 12	  y: z.int(),
 13	  w: z.int().positive(),
 14	  h: z.int().positive(),
 15	});
 16	
 17	export type Box = z.infer<typeof boxSchema>;
 18	
 19	/** §8's move timing, restricted to what a fighter's own move can be: numeric active frames, blockable or not. */
 20	export type DuelMoveTiming = Omit<MoveTiming, "active" | "onBlock"> & {
 21	  readonly active: number;
 22	  readonly onBlock: { readonly kind: "frames"; readonly advantage: number } | { readonly kind: "unguardable" };
 23	};
 24	
 25	export type GuardLevel = "high" | "mid" | "low" | "unguardable";
 26	export type MoveCategory = "light" | "heavy" | "special" | "throw";
 27	
 28	/**
 29	 * One move. Frame counts are 60 Hz frames: `startup` frames come before the first active frame, then `active`, then
 30	 * `recovery`. Distances and velocities are sub-pixels (per frame).
 31	 */
 32	export interface DuelMove {
 33	  readonly timing: DuelMoveTiming;
 34	  readonly kind: "strike" | "throw";
 35	  /** Decides what blocking it costs (§7) and which rules apply. */
 36	  readonly category: MoveCategory;
 37	  /** The hurtbox the attacker uses while performing the move. */
 38	  readonly stance: "standing" | "crouching";
 39	  readonly guard: GuardLevel;
 40	  /** One box for the whole active phase. */
 41	  readonly hitbox: Box;
 42	  /** Before combo scaling. */
 43	  readonly damage: number;
 44	  /** Frames the defender cannot act after a hit, counting the contact frame; for a throw, the knockdown after it. */
 45	  readonly hitstun: number;
 46	  /** Frames the defender cannot act after blocking, counting the contact frame; 0 for a throw. */
 47	  readonly blockstun: number;
 48	  readonly hitPushback: number;
 49	  readonly blockPushback: number;
 50	  /** Upward velocity given to the defender on hit (sub-pixels per frame); 0 leaves a grounded defender grounded. */
 51	  readonly launch: number;
 52	  /** Forward velocity of the attacker during startup and active frames. */
 53	  readonly advance: number;
 54	  /** Frames from the move's first frame during which strikes pass through the attacker. */
 55	  readonly strikeInvulnerable: number;
 56	  /** Stamina the defender spends to block it. */
 57	  readonly guardStaminaCost: number;
 58	}
 59	
 60	/** Which move each input starts (§8): down + heavy is the low sweep, forward + heavy the launcher, down + light the anti-air. */
 61	export interface DuelCommands {
 62	  readonly light: string;
 63	  readonly downLight: string;
 64	  readonly heavy: string;
 65	  readonly downHeavy: string;
 66	  readonly forwardHeavy: string;
 67	  readonly special1: string;
 68	  readonly special2: string;
 69	  readonly throw: string;
 70	}
 71	
 72	/** A fighter's body and movement. Distances are sub-pixels, speeds sub-pixels per frame, durations frames. */
 73	export interface DuelFighter {
 74	  readonly hurtboxes: { readonly standing: Box; readonly crouching: Box; readonly airborne: Box };
 75	  /** Two fighters' pushboxes never overlap: centred on the origin, `halfWidth` either side, `height` tall. */
 76	  readonly pushbox: { readonly halfWidth: number; readonly height: number };
 77	  readonly walkForwardSpeed: number;
 78	  readonly walkBackSpeed: number;
 79	  readonly jumpVelocity: number;
 80	  readonly jumpSpeedX: number;
 81	  /** Subtracted from the vertical velocity every airborne frame. */
 82	  readonly gravity: number;
 83	  readonly dashFrames: number;
 84	  readonly dashSpeed: number;
 85	  readonly backdashFrames: number;
 86	  readonly backdashSpeed: number;
 87	  /** Recovery of both fighters after a throw escape or two throws breaking each other. */
 88	  readonly throwBreakFrames: number;
 89	  /** How far each fighter is pushed away from the other when a throw breaks. */
 90	  readonly throwBreakPushback: number;
 91	}
 92	
 93	/** The single-plane arena: a floor between two walls. */
 94	export interface DuelArena {
 95	  readonly subPixelsPerPixel: number;
 96	  /** Wall to wall, in sub-pixels. Fighters' origins stay a pushbox half-width inside the walls. */
 97	  readonly width: number;
 98	  /** Distance between the two fighters' origins at the start, placed symmetrically about the centre. */
 99	  readonly startGap: number;
100	}
101	
102	/** §7's round, stamina and combo rules as numbers. */
103	export interface DuelRules {
104	  readonly roundFrames: number;
105	  readonly overtimeFrames: number;
106	  readonly maxHealth: number;
107	  readonly maxStamina: number;
108	  readonly dashStaminaCost: number;
109	  readonly guardStaminaCost: { readonly light: number; readonly heavy: number; readonly special: number };
110	  /** Frames without spending or blocking before stamina regenerates. */
111	  readonly staminaRegenDelayFrames: number;
112	  /** After the delay, one stamina point every this many frames (3 frames is 20 a second). */
113	  readonly staminaRegenIntervalFrames: number;
114	  readonly guardBreakStaggerFrames: number;
115	  readonly guardBreakStaminaRestore: number;
116	  /** Percent of base damage for the first, second, ... damaging hit of a combo. */
117	  readonly comboScaling: readonly number[];
118	  /** The damaging hit that forces the non-juggleable recovery. */
119	  readonly comboCap: number;
120	  readonly forcedRecoveryFrames: number;
121	  readonly throwEscapeFrames: number;
122	  readonly inputBufferFrames: number;
123	}
124	
125	/** Everything the duel step reads. `version` identifies it all; a duel state records it. */
126	export interface DuelMoveset {
127	  readonly version: string;
128	  readonly rules: DuelRules;
129	  readonly arena: DuelArena;
130	  readonly fighter: DuelFighter;
131	  readonly moves: readonly DuelMove[];
132	  readonly commands: DuelCommands;
133	}
134	
135	const count = z.int().nonnegative();
136	const positive = z.int().positive();
137	
138	export const duelMoveSchema = z
139	  .strictObject({
140	    // The timing is §8's own schema, so its rules (positive startup and active frames, block advantage within
141	    // active + recovery) are checked in one place.
142	    timing: moveTimingSchema,
143	    kind: z.enum(["strike", "throw"]),
144	    category: z.enum(["light", "heavy", "special", "throw"]),
145	    stance: z.enum(["standing", "crouching"]),
146	    guard: z.enum(["high", "mid", "low", "unguardable"]),
147	    hitbox: boxSchema,
148	    damage: positive,
149	    hitstun: positive,
150	    blockstun: count,
151	    hitPushback: count,
152	    blockPushback: count,
153	    launch: count,
154	    advance: count,
155	    strikeInvulnerable: count,
156	    guardStaminaCost: count,
157	  })
158	  .superRefine((move, ctx) => {
159	    const { timing } = move;
160	    if (timing.active === "projectile-life") {
161	      ctx.addIssue({ code: "custom", path: ["timing", "active"], message: "a fighter's move needs a number of active frames" });
162	      return;
163	    }
164	    const isThrow = move.kind === "throw";
165	    if (isThrow !== (move.category === "throw") || isThrow !== (move.guard === "unguardable")) {
166	      ctx.addIssue({ code: "custom", path: ["kind"], message: "a throw, and only a throw, has the throw category and is unguardable" });
167	    }
168	    if (isThrow) {
169	      if (timing.onBlock.kind !== "unguardable") ctx.addIssue({ code: "custom", path: ["timing", "onBlock"], message: "a throw is unguardable" });
170	      if (move.blockstun !== 0) ctx.addIssue({ code: "custom", path: ["blockstun"], message: "a throw cannot be blocked" });
171	    } else if (timing.onBlock.kind !== "frames") {
172	      ctx.addIssue({ code: "custom", path: ["timing", "onBlock"], message: "a strike needs a frame advantage on block" });
173	    } else if (move.blockstun !== timing.active + timing.recovery + timing.onBlock.advantage) {
174	      // Contact on the first active frame, which is also the defender's first blockstun frame.
175	      ctx.addIssue({
176	        code: "custom",
177	        path: ["blockstun"],
178	        message: `blockstun ${move.blockstun} does not give ${timing.onBlock.advantage} on block (needs ${timing.active + timing.recovery + timing.onBlock.advantage})`,
179	      });
180	    }
181	    if (move.strikeInvulnerable > timing.startup) {
182	      ctx.addIssue({ code: "custom", path: ["strikeInvulnerable"], message: "strike invulnerability cannot outlast startup" });
183	    }
184	  });
185	
186	const hurtboxesSchema = z.strictObject({ standing: boxSchema, crouching: boxSchema, airborne: boxSchema });
187	
188	export const duelFighterSchema = z.strictObject({
189	  hurtboxes: hurtboxesSchema,
190	  pushbox: z.strictObject({ halfWidth: positive, height: positive }),
191	  walkForwardSpeed: positive,
192	  walkBackSpeed: positive,
193	  jumpVelocity: positive,
194	  jumpSpeedX: count,
195	  gravity: positive,
196	  dashFrames: positive,
197	  dashSpeed: positive,
198	  backdashFrames: positive,
199	  backdashSpeed: positive,
200	  throwBreakFrames: positive,
201	  throwBreakPushback: count,
202	});
203	
204	export const duelArenaSchema = z.strictObject({ subPixelsPerPixel: positive, width: positive, startGap: positive });
205	
206	export const duelRulesSchema = z.strictObject({
207	  roundFrames: positive,
208	  overtimeFrames: positive,
209	  maxHealth: positive,
210	  maxStamina: positive,
211	  dashStaminaCost: count,
212	  guardStaminaCost: z.strictObject({ light: count, heavy: count, special: count }),
213	  staminaRegenDelayFrames: count,
214	  staminaRegenIntervalFrames: positive,
215	  guardBreakStaggerFrames: positive,
216	  guardBreakStaminaRestore: count,
217	  comboScaling: z.array(z.int().min(1).max(100)).min(1),
218	  comboCap: positive,
219	  forcedRecoveryFrames: positive,
220	  throwEscapeFrames: positive,
221	  inputBufferFrames: positive,
222	});
223	
224	const commandsSchema = z.strictObject({
225	  light: z.string(),
226	  downLight: z.string(),
227	  heavy: z.string(),
228	  downHeavy: z.string(),
229	  forwardHeavy: z.string(),
230	  special1: z.string(),
231	  special2: z.string(),
232	  throw: z.string(),
233	});
234	
235	export const duelMovesetSchema = z
236	  .strictObject({
237	    version: z.string().min(1),
238	    rules: duelRulesSchema,
239	    arena: duelArenaSchema,
240	    fighter: duelFighterSchema,
241	    moves: z.array(duelMoveSchema).min(1),
242	    commands: commandsSchema,
243	  })
244	  .superRefine((moveset, ctx) => {
245	    const { rules, arena, fighter } = moveset;
246	    const byId = new Map<string, (typeof moveset.moves)[number]>();
247	    moveset.moves.forEach((move, index) => {
248	      const id = move.timing.id;
249	      if (byId.has(id)) ctx.addIssue({ code: "custom", path: ["moves", index, "timing", "id"], message: `${id}: duplicate move id` });
250	      byId.set(id, move);
251	      // A move named like a §8 baseline row must use that row's timing exactly.
252	      const baseline = baselineFrameBudgets.find((row) => row.id === id);
253	      if (baseline !== undefined && !sameTiming(move.timing, baseline)) {
254	        ctx.addIssue({ code: "custom", path: ["moves", index, "timing"], message: `${id}: timing differs from §8's baseline row` });
255	      }
256	      const cost = move.category === "throw" ? 0 : rules.guardStaminaCost[move.category];
257	      if (move.guardStaminaCost !== cost) {
258	        ctx.addIssue({ code: "custom", path: ["moves", index, "guardStaminaCost"], message: `${id}: blocking a ${move.category} costs ${cost}` });
259	      }
260	    });
261	    for (const [command, id] of Object.entries(moveset.commands)) {
262	      const move = byId.get(id);
263	      if (move === undefined) {
264	        ctx.addIssue({ code: "custom", path: ["commands", command], message: `unknown move "${id}"` });
265	      } else if ((command === "throw") !== (move.kind === "throw")) {
266	        ctx.addIssue({ code: "custom", path: ["commands", command], message: `"${id}" is the wrong kind of move for ${command}` });
267	      }
268	    }
269	    if (rules.comboCap > rules.comboScaling.length) {
270	      ctx.addIssue({ code: "custom", path: ["rules", "comboCap"], message: "every hit up to the cap needs a scaling step" });
271	    }
272	    if (rules.dashStaminaCost > rules.maxStamina) {
273	      ctx.addIssue({ code: "custom", path: ["rules", "dashStaminaCost"], message: "a dash would cost more than full stamina" });
274	    }
275	    // Symmetric start positions need even distances, and both fighters must start inside the walls and out of reach
276	    // of every move (§6: no free opening hit).
277	    if (arena.width % 2 !== 0 || arena.startGap % 2 !== 0) {
278	      ctx.addIssue({ code: "custom", path: ["arena"], message: "arena width and start gap must be even" });
279	    }
280	    if (arena.startGap > arena.width - 2 * fighter.pushbox.halfWidth) {
281	      ctx.addIssue({ code: "custom", path: ["arena", "startGap"], message: "the start positions lie outside the walls" });
282	    }
283	    const hurtReach = Math.max(...Object.values(fighter.hurtboxes).map((box) => Math.max(box.x + box.w, -box.x)));
284	    const hitReach = Math.max(...moveset.moves.map((move) => move.hitbox.x + move.hitbox.w));
285	    if (arena.startGap < hitReach + hurtReach) {
286	      ctx.addIssue({ code: "custom", path: ["arena", "startGap"], message: "fighters would start within reach of a move" });
287	    }
288	  });
289	
290	function sameTiming(a: MoveTiming, b: MoveTiming): boolean {
291	  const advantage = (timing: MoveTiming) => (timing.onBlock.kind === "frames" ? timing.onBlock.advantage : null);
292	  return (
293	    a.id === b.id &&
294	    a.name === b.name &&
295	    a.startup === b.startup &&
296	    a.active === b.active &&
297	    a.recovery === b.recovery &&
298	    a.onBlock.kind === b.onBlock.kind &&
299	    advantage(a) === advantage(b)
300	  );
301	}
302	
303	export function validateDuelMove(candidate: unknown): ValidationResult<DuelMove> {
304	  const parsed = duelMoveSchema.safeParse(candidate);
305	  return parsed.success ? { ok: true, value: parsed.data as DuelMove } : { ok: false, issues: formatIssues(parsed.error) };
306	}
307	
308	export function validateDuelMoveset(candidate: unknown): ValidationResult<DuelMoveset> {
309	  const parsed = duelMovesetSchema.safeParse(candidate);
310	  return parsed.success ? { ok: true, value: parsed.data as DuelMoveset } : { ok: false, issues: formatIssues(parsed.error) };
311	}
  1	import { baselineFrameBudgets } from "../frameBudgets.js";
  2	import type { DuelArena, DuelFighter, DuelMove, DuelMoveset, DuelRules } from "./schema.js";
  3	
  4	/**
  5	 * Identifies everything in this file. A duel state records it, and restoring or replaying a duel against other data
  6	 * is refused, so bump it on every change here (a simulation test pins the data's hash to it).
  7	 */
  8	export const MOVESET_VERSION = "duelist-1";
  9	
 10	/** 16 sub-pixels per arena pixel; `px(4)` is 4 pixels. */
 11	const SUB_PIXELS_PER_PIXEL = 16;
 12	const px = (pixels: number) => pixels * SUB_PIXELS_PER_PIXEL;
 13	
 14	/** A §8 baseline row by id: the four baseline moves take their timing from the table itself, never a copy. */
 15	function baseline<Id extends (typeof baselineFrameBudgets)[number]["id"]>(id: Id) {
 16	  const row = baselineFrameBudgets.find((candidate) => candidate.id === id);
 17	  if (row === undefined) throw new Error(`no baseline frame budget "${id}"`);
 18	  return row as Extract<(typeof baselineFrameBudgets)[number], { id: Id }>;
 19	}
 20	
 21	export const duelRules: DuelRules = {
 22	  roundFrames: 3600,
 23	  overtimeFrames: 600,
 24	  maxHealth: 1000,
 25	  maxStamina: 100,
 26	  dashStaminaCost: 20,
 27	  guardStaminaCost: { light: 10, heavy: 25, special: 20 },
 28	  staminaRegenDelayFrames: 60,
 29	  staminaRegenIntervalFrames: 3,
 30	  guardBreakStaggerFrames: 30,
 31	  guardBreakStaminaRestore: 30,
 32	  comboScaling: [100, 80, 65, 50, 40],
 33	  comboCap: 5,
 34	  forcedRecoveryFrames: 40,
 35	  throwEscapeFrames: 10,
 36	  inputBufferFrames: 4,
 37	};
 38	
 39	/** 640 × 16 px wide; the fighters start 192 px apart, beyond every move's reach. */
 40	export const duelArena: DuelArena = {
 41	  subPixelsPerPixel: SUB_PIXELS_PER_PIXEL,
 42	  width: px(640),
 43	  startGap: px(192),
 44	};
 45	
 46	export const duelistFighter: DuelFighter = {
 47	  hurtboxes: {
 48	    standing: { x: px(-20), y: 0, w: px(40), h: px(96) },
 49	    crouching: { x: px(-22), y: 0, w: px(44), h: px(56) },
 50	    airborne: { x: px(-18), y: 0, w: px(36), h: px(80) },
 51	  },
 52	  pushbox: { halfWidth: px(16), height: px(80) },
 53	  walkForwardSpeed: 48,
 54	  walkBackSpeed: 40,
 55	  // 160 up, 8 gravity: 40 frames in the air, apex about 105 px, high enough to pass over a standing pushbox.
 56	  jumpVelocity: 160,
 57	  jumpSpeedX: 40,
 58	  gravity: 8,
 59	  dashFrames: 16,
 60	  dashSpeed: 64,
