 65	};
 66	
 67	const G = duelRules.guardStaminaCost;
 68	
 69	/**
 70	 * Hitboxes face right, relative to the fighter's origin. Blockstun always equals active + recovery + the on-block
 71	 * advantage (contact on the first active frame).
 72	 *
 73	 * The heavy mid and the jab are tuned together so the heavy is punishable by a jab at every spacing it can leave:
 74	 * the heavy reaches a standing hurtbox up to 80 px away (hitbox to 60 px, hurtbox 20 px wide either side) and pushes
 75	 * the blocker back 4 px, so it leaves at most 84 px minus one sub-pixel; the jab reaches 64 + 20 = 84 px.
 76	 */
 77	export const duelistMoves: readonly DuelMove[] = [
 78	  {
 79	    timing: baseline("jab"),
 80	    kind: "strike",
 81	    category: "light",
 82	    stance: "standing",
 83	    guard: "mid",
 84	    hitbox: { x: px(16), y: px(40), w: px(48), h: px(32) },
 85	    damage: 45,
