132	    timing: { id: "launcher", name: "Launcher", startup: 16, active: 4, recovery: 28, onBlock: { kind: "frames", advantage: -18 } },
133	    kind: "strike",
134	    category: "heavy",
135	    stance: "standing",
136	    guard: "mid",
137	    hitbox: { x: px(12), y: px(16), w: px(40), h: px(64) },
138	    damage: 100,
139	    hitstun: 40,
140	    blockstun: 14,
141	    hitPushback: px(2),
142	    blockPushback: px(4),
143	    launch: 96,
144	    advance: 0,
145	    strikeInvulnerable: 0,
146	    guardStaminaCost: G.heavy,
147	  },
148	  {
149	    // Worker's choice: the universal anti-air, a fast upward swing; high, so it passes over a crouching fighter.
150	    timing: { id: "anti-air", name: "Anti-air", startup: 6, active: 5, recovery: 20, onBlock: { kind: "frames", advantage: -14 } },
151	    kind: "strike",
152	    category: "light",
153	    stance: "standing",
154	    guard: "high",
155	    hitbox: { x: 0, y: px(48), w: px(48), h: px(96) },
156	    damage: 70,
157	    hitstun: 26,
158	    blockstun: 11,
159	    hitPushback: px(4),
160	    blockPushback: px(3),
161	    launch: 0,
162	    advance: 0,
163	    strikeInvulnerable: 0,
164	    guardStaminaCost: G.light,
165	  },
166	  {
167	    timing: baseline("throw"),
168	    kind: "throw",
169	    category: "throw",
170	    stance: "standing",
171	    guard: "unguardable",
172	    hitbox: { x: 0, y: 0, w: px(32), h: px(80) },
173	    damage: 120,
174	    // The knockdown after the throw lands.
175	    hitstun: 30,
176	    blockstun: 0,
177	    hitPushback: 0,
178	    blockPushback: 0,
179	    launch: 0,
180	    advance: 0,
181	    strikeInvulnerable: 0,
182	    guardStaminaCost: 0,
183	  },
184	  {
185	    // Worker's choice: the Duelist's first special, a lunge that covers about 72 px before its hitbox ends.
186	    timing: { id: "advancing-thrust", name: "Advancing thrust", startup: 14, active: 4, recovery: 26, onBlock: { kind: "frames", advantage: -18 } },
187	    kind: "strike",
188	    category: "special",
189	    stance: "standing",
190	    guard: "mid",
191	    hitbox: { x: px(16), y: px(24), w: px(40), h: px(40) },
192	    damage: 130,
193	    hitstun: 28,
194	    blockstun: 12,
195	    hitPushback: px(8),
196	    blockPushback: px(6),
197	    launch: 0,
198	    advance: 64,
199	    strikeInvulnerable: 0,
200	    guardStaminaCost: G.special,
201	  },
202	  {
203	    // Worker's choice: the second special, a reversal slash that strikes pass through during its whole startup; very
204	    // unsafe on block or whiff.
205	    timing: { id: "counter-slash", name: "Counter slash", startup: 8, active: 3, recovery: 30, onBlock: { kind: "frames", advantage: -22 } },
206	    kind: "strike",
207	    category: "special",
208	    stance: "standing",
