 18	
 19	/** §8's move timing, restricted to what a fighter's own move can be: numeric active frames, blockable or not. */
 20	export type DuelMoveTiming = Omit<MoveTiming, "active" | "onBlock"> & {
 21	  readonly active: number;
 22	  readonly onBlock: { readonly kind: "frames"; readonly advantage: number } | { readonly kind: "unguardable" };
 23	};
 24	
 25	export type GuardLevel = "high" | "mid" | "low" | "unguardable";
 26	export type MoveCategory = "light" | "heavy" | "special" | "throw";
 27	
 28	/**
 29	 * One move. Frame counts are 60 Hz frames: `startup` frames come before the first active frame, then `active`, then
 30	 * `recovery`. Distances and velocities are sub-pixels (per frame).
 31	 */
 32	export interface DuelMove {
 33	  readonly timing: DuelMoveTiming;
 34	  readonly kind: "strike" | "throw";
 35	  /** Decides what blocking it costs (§7) and which rules apply. */
 36	  readonly category: MoveCategory;
 37	  /** The hurtbox the attacker uses while performing the move. */
 38	  readonly stance: "standing" | "crouching";
 39	  readonly guard: GuardLevel;
 40	  /** One box for the whole active phase. */
 41	  readonly hitbox: Box;
 42	  /** Before combo scaling. */
 43	  readonly damage: number;
 44	  /** Frames the defender cannot act after a hit, counting the contact frame; for a throw, the knockdown after it. */
 45	  readonly hitstun: number;
 46	  /** Frames the defender cannot act after blocking, counting the contact frame; 0 for a throw. */
 47	  readonly blockstun: number;
 48	  readonly hitPushback: number;
 49	  readonly blockPushback: number;
 50	  /** Upward velocity given to the defender on hit (sub-pixels per frame); 0 leaves a grounded defender grounded. */
 51	  readonly launch: number;
 52	  /** Forward velocity of the attacker during startup and active frames. */
 53	  readonly advance: number;
 54	  /** Frames from the move's first frame during which strikes pass through the attacker. */
 55	  readonly strikeInvulnerable: number;
 56	  /** Stamina the defender spends to block it. */
 57	  readonly guardStaminaCost: number;
 58	}
 59	
 60	/** Which move each input starts (§8): down + heavy is the low sweep, forward + heavy the launcher, down + light the anti-air. */
