206	export const duelRulesSchema = z.strictObject({
207	  roundFrames: positive,
208	  overtimeFrames: positive,
209	  maxHealth: positive,
210	  maxStamina: positive,
211	  dashStaminaCost: count,
212	  guardStaminaCost: z.strictObject({ light: count, heavy: count, special: count }),
213	  staminaRegenDelayFrames: count,
214	  staminaRegenIntervalFrames: positive,
215	  guardBreakStaggerFrames: positive,
216	  guardBreakStaminaRestore: count,
217	  comboScaling: z.array(z.int().min(1).max(100)).min(1),
218	  comboCap: positive,
219	  forcedRecoveryFrames: positive,
220	  throwEscapeFrames: positive,
221	  inputBufferFrames: positive,
222	});
223	
224	const commandsSchema = z.strictObject({
225	  light: z.string(),
226	  downLight: z.string(),
227	  heavy: z.string(),
228	  downHeavy: z.string(),
229	  forwardHeavy: z.string(),
230	  special1: z.string(),
231	  special2: z.string(),
