235	export const duelMovesetSchema = z
236	  .strictObject({
237	    version: z.string().min(1),
238	    rules: duelRulesSchema,
239	    arena: duelArenaSchema,
240	    fighter: duelFighterSchema,
241	    moves: z.array(duelMoveSchema).min(1),
242	    commands: commandsSchema,
243	  })
244	  .superRefine((moveset, ctx) => {
245	    const { rules, arena, fighter } = moveset;
246	    const byId = new Map<string, (typeof moveset.moves)[number]>();
247	    moveset.moves.forEach((move, index) => {
248	      const id = move.timing.id;
249	      if (byId.has(id)) ctx.addIssue({ code: "custom", path: ["moves", index, "timing", "id"], message: `${id}: duplicate move id` });
250	      byId.set(id, move);
251	      // A move named like a §8 baseline row must use that row's timing exactly.
252	      const baseline = baselineFrameBudgets.find((row) => row.id === id);
253	      if (baseline !== undefined && !sameTiming(move.timing, baseline)) {
254	        ctx.addIssue({ code: "custom", path: ["moves", index, "timing"], message: `${id}: timing differs from §8's baseline row` });
255	      }
256	      const cost = move.category === "throw" ? 0 : rules.guardStaminaCost[move.category];
257	      if (move.guardStaminaCost !== cost) {
258	        ctx.addIssue({ code: "custom", path: ["moves", index, "guardStaminaCost"], message: `${id}: blocking a ${move.category} costs ${cost}` });
259	      }
260	    });
261	    for (const [command, id] of Object.entries(moveset.commands)) {
262	      const move = byId.get(id);
263	      if (move === undefined) {
264	        ctx.addIssue({ code: "custom", path: ["commands", command], message: `unknown move "${id}"` });
265	      } else if ((command === "throw") !== (move.kind === "throw")) {
266	        ctx.addIssue({ code: "custom", path: ["commands", command], message: `"${id}" is the wrong kind of move for ${command}` });
267	      }
268	    }
269	    if (rules.comboCap > rules.comboScaling.length) {
270	      ctx.addIssue({ code: "custom", path: ["rules", "comboCap"], message: "every hit up to the cap needs a scaling step" });
271	    }
272	    if (rules.dashStaminaCost > rules.maxStamina) {
273	      ctx.addIssue({ code: "custom", path: ["rules", "dashStaminaCost"], message: "a dash would cost more than full stamina" });
274	    }
275	    // Symmetric start positions need even distances, and both fighters must start inside the walls and out of reach
276	    // of every move (§6: no free opening hit).
277	    if (arena.width % 2 !== 0 || arena.startGap % 2 !== 0) {
278	      ctx.addIssue({ code: "custom", path: ["arena"], message: "arena width and start gap must be even" });
279	    }
280	    if (arena.startGap > arena.width - 2 * fighter.pushbox.halfWidth) {
281	      ctx.addIssue({ code: "custom", path: ["arena", "startGap"], message: "the start positions lie outside the walls" });
282	    }
283	    const hurtReach = Math.max(...Object.values(fighter.hurtboxes).map((box) => Math.max(box.x + box.w, -box.x)));
284	    const hitReach = Math.max(...moveset.moves.map((move) => move.hitbox.x + move.hitbox.w));
285	    if (arena.startGap < hitReach + hurtReach) {
286	      ctx.addIssue({ code: "custom", path: ["arena", "startGap"], message: "fighters would start within reach of a move" });
287	    }
288	  });
