186	    timing: { id: "advancing-thrust", name: "Advancing thrust", startup: 14, active: 4, recovery: 26, onBlock: { kind: "frames", advantage: -18 } },
187	    kind: "strike",
188	    category: "special",
189	    stance: "standing",
190	    guard: "mid",
191	    hitbox: { x: px(16), y: px(24), w: px(40), h: px(40) },
192	    damage: 130,
193	    hitstun: 28,
194	    blockstun: 12,
195	    hitPushback: px(8),
196	    blockPushback: px(6),
197	    launch: 0,
198	    advance: 64,
199	    strikeInvulnerable: 0,
200	    guardStaminaCost: G.special,
201	  },
202	  {
203	    // Worker's choice: the second special, a reversal slash that strikes pass through during its whole startup; very
204	    // unsafe on block or whiff.
205	    timing: { id: "counter-slash", name: "Counter slash", startup: 8, active: 3, recovery: 30, onBlock: { kind: "frames", advantage: -22 } },
206	    kind: "strike",
207	    category: "special",
208	    stance: "standing",
209	    guard: "high",
210	    hitbox: { x: px(12), y: px(48), w: px(36), h: px(48) },
211	    damage: 120,
212	    hitstun: 30,
213	    blockstun: 11,
214	    hitPushback: px(8),
215	    blockPushback: px(4),
216	    launch: 0,
217	    advance: 0,
218	    strikeInvulnerable: 8,
219	    guardStaminaCost: G.special,
220	  },
221	];
222	
223	export const duelistMoveset: DuelMoveset = {
224	  version: MOVESET_VERSION,
225	  rules: duelRules,
226	  arena: duelArena,
227	  fighter: duelistFighter,
228	  moves: duelistMoves,
229	  commands: {
230	    light: "jab",
231	    downLight: "anti-air",
232	    heavy: "heavy-mid",
233	    downHeavy: "low-sweep",
