  1	import { DUEL_BUTTONS, DUEL_INPUT, type DuelMove, type DuelMoveset } from "@pirate-sea-race/content/moves";
  2	import { clampInt, divTrunc } from "../fixed.js";
  3	import { overlaps, worldBox, type Facing } from "./boxes.js";
  4	import { directions, sanitizeDuelInput, type DuelInputs } from "./input.js";
  5	import {
  6	  canAct,
  7	  findMove,
  8	  moveDuration,
  9	  type DuelConfig,
 10	  type DuelEvent,
 11	  type DuelResult,
 12	  type DuelState,
 13	  type FighterState,
 14	  type InputBuffer,
 15	  type PlayerIndex,
 16	  type Stance,
 17	} from "./state.js";
 18	
 19	/** One player's input for this frame, read against last frame's held buttons. */
 20	interface FrameInput {
 21	  readonly bits: number;
 22	  readonly h: -1 | 0 | 1;
 23	  readonly v: -1 | 0 | 1;
 24	  readonly buffer: InputBuffer;
 25	}
 26	
 27	/** What one fighter's move does to the other this frame, detected against the start-of-frame state. */
 28	interface Contact {
 29	  readonly kind: "hit" | "block" | "grab";
 30	  readonly move: DuelMove;
 31	  /** The defender's stance at contact. */
 32	  readonly stance: Stance;
 33	}
 34	
 35	type Pair<T> = readonly [T, T];
 36	
 37	const OTHER = [1, 0] as const;
 38	
 39	/**
 40	 * Advances the duel by one 60 Hz frame (order of operations in docs/duel.md):
 41	 *
 42	 * 1. read both inputs (opposite directions cancel; newly pressed buttons enter the 4-frame buffer);
 43	 * 2. detect every hit, block and grab of the frame against the start-of-frame state of both fighters;
 44	 * 3. settle same-frame interactions (throw against throw breaks both; an active strike beats a throw);
 45	 * 4. apply all results together, damage and stamina from start-of-frame values; fighters not struck advance their
 46	 *    action or start a new one from their input;
 47	 * 5. move, apply gravity, keep fighters inside the walls and apart;
 48	 * 6. regenerate stamina, then decide KO, timeout and overtime from both fighters' health.
 49	 *
 50	 * Neither fighter is processed "first": every decision for one fighter reads only the start-of-frame state and the
 51	 * frame's inputs. The input state is never mutated. A finished duel only advances its frame counter.
 52	 */
 53	export function stepDuel(config: DuelConfig, state: DuelState, inputs: DuelInputs): DuelState {
 54	  const { moveset } = config;
 55	  if (state.movesetVersion !== moveset.version) {
 56	    throw new Error(`the duel runs on moveset ${state.movesetVersion}, not ${moveset.version}`);
 57	  }
 58	  const frame = state.frame + 1;
 59	  if (state.result !== null) return { ...state, frame, events: [] };
 60	
 61	  const fighters = state.fighters;
 62	  const input: Pair<FrameInput> = [readInput(moveset, fighters[0], inputs[0]), readInput(moveset, fighters[1], inputs[1])];
 63	
 64	  // 2. Detection, each against the same start-of-frame state.
 65	  let contacts: Pair<Contact | null> = [detect(moveset, fighters, 0, input), detect(moveset, fighters, 1, input)];
 66	
 67	  // 3. Same-frame interactions.
 68	  const clash = contacts[0]?.kind === "grab" && contacts[1]?.kind === "grab";
 69	  if (clash) {
 70	    contacts = [null, null];
 71	  } else {
 72	    contacts = [
 73	      contacts[0]?.kind === "grab" && strikeActive(moveset, fighters[1]) ? null : contacts[0],
 74	      contacts[1]?.kind === "grab" && strikeActive(moveset, fighters[0]) ? null : contacts[1],
 75	    ];
 76	  }
 77	  const escape: Pair<boolean> = [escapes(fighters[0], input[0]), escapes(fighters[1], input[1])];
 78	  const throwBreak = clash || escape[0] || escape[1];
 79	
 80	  // Displacement from pushback and throw breaks, from start-of-frame positions.
 81	  const shift = [0, 0];
 82	  const minX = moveset.fighter.pushbox.halfWidth;
 83	  const maxX = moveset.arena.width - minX;
 84	  for (const attacker of [0, 1] as const) {
 85	    const contact = contacts[attacker];
 86	    if (contact === null || contact.kind === "grab") continue;
 87	    const defender = OTHER[attacker];
 88	    const def = fighters[defender];
 89	    const push = contact.kind === "hit" ? contact.move.hitPushback : contact.move.blockPushback;
 90	    const direction = awayFrom(def, fighters[attacker]);
 91	    const target = clampInt(def.x + direction * push, minX, maxX);
 92	    shift[defender]! += target - def.x;
 93	    // Against a wall, the rest of the pushback moves the attacker back instead.
 94	    shift[attacker]! -= direction * (push - Math.abs(target - def.x));
 95	  }
 96	  if (throwBreak) {
 97	    for (const index of [0, 1] as const) {
 98	      shift[index]! += awayFrom(fighters[index], fighters[OTHER[index]]) * moveset.fighter.throwBreakPushback;
 99	    }
100	  }
101	
102	  // 4. Apply results and advance actions.
103	  const events: DuelEvent[] = [];
104	  const spent = [false, false];
105	  const next = ([0, 1] as const).map((index): FighterState => {
106	    const self = fighters[index];
107	    const opponent = fighters[OTHER[index]];
108	    const incoming = contacts[OTHER[index]];
109	    const outgoing = contacts[index];
110	    const own = input[index];
111	    let fighter: FighterState = { ...self, held: own.bits, buffer: own.buffer };
112	    if (throwBreak) {
113	      // Two throws on one frame, or an escape: both fighters recover apart with no damage.
114	      if (clash) events.push({ kind: "throw-clash", attacker: index, moveId: self.moveId ?? "", damage: 0 });
115	      if (escape[OTHER[index]]) events.push({ kind: "throw-escape", attacker: index, moveId: moveset.commands.throw, damage: 0 });
116	      return startTimed(fighter, "throw-break", moveset.fighter.throwBreakFrames);
117	    }
118	    if (incoming !== null) {
119	      const attacker = OTHER[index];
120	      const result = react(moveset, fighter, incoming, attacker);
121	      events.push(result.event);
122	      if (incoming.kind === "block") spent[index] = true;
123	      return result.fighter;
124	    }
125	    if (outgoing !== null) fighter = { ...fighter, moveHit: true };
126	    if (fighter.action === "thrown") {
127	      if (fighter.timer > 0) return { ...fighter, timer: fighter.timer - 1, actionFrame: fighter.actionFrame + 1 };
128	      // The escape window ran out: the throw lands.
129	      const move = findMove(moveset, moveset.commands.throw);
130	      const damage = scaledDamage(moveset, move.damage, fighter.combo);
131	      events.push({ kind: "throw", attacker: OTHER[index], moveId: move.timing.id, damage });
132	      return {
133	        ...startTimed(fighter, "knockdown", move.hitstun),
134	        health: Math.max(0, fighter.health - damage),
135	        combo: fighter.combo + 1,
136	      };
137	    }
138	    if (!canAct(self)) return progress(moveset, fighter);
139	    const started = choose(moveset, fighter, opponent, own);
140	    if (started.action === "dash" || started.action === "backdash") spent[index] = true;
141	    return started;
142	  }) as unknown as Pair<FighterState>;
143	
144	  // 5. Movement: velocities, gravity and landing, walls, then pushboxes.
145	  const moved = ([0, 1] as const).map((index) => move(moveset, next[index], shift[index]!)) as unknown as Pair<FighterState>;
146	  const separated = separate(moveset, moved);
147	
148	  // 6. Stamina regeneration, then the result.
149	  const rules = moveset.rules;
150	  const final = ([0, 1] as const).map((index): FighterState => {
151	    const fighter = separated[index];
152	    if (spent[index]) return { ...fighter, staminaIdle: 0 };
153	    const idle = fighter.staminaIdle + 1;
154	    const regenerates =
155	      idle > rules.staminaRegenDelayFrames && (idle - rules.staminaRegenDelayFrames) % rules.staminaRegenIntervalFrames === 0;
156	    return { ...fighter, staminaIdle: idle, stamina: regenerates ? Math.min(rules.maxStamina, fighter.stamina + 1) : fighter.stamina };
157	  }) as unknown as Pair<FighterState>;
158	
159	  const result = decide(moveset, state, frame, final);
160	  return {
161	    ...state,
162	    frame,
163	    phase: result === null ? (state.phase === "round" && frame >= rules.roundFrames ? "overtime" : state.phase) : "over",
164	    fighters: final,
165	    events,
166	    result,
167	  };
168	}
169	
170	function readInput(moveset: DuelMoveset, fighter: FighterState, raw: number): FrameInput {
171	  const bits = sanitizeDuelInput(raw);
172	  const pressed = bits & ~fighter.held;
173	  const buffer = Object.fromEntries(
174	    DUEL_BUTTONS.map((button) => [
175	      button,
176	      (pressed & DUEL_INPUT[button]) !== 0 ? moveset.rules.inputBufferFrames : Math.max(0, fighter.buffer[button] - 1),
177	    ]),
178	  ) as unknown as InputBuffer;
179	  return { bits, ...directions(bits), buffer };
180	}
181	
182	/** -1 or 1: the direction pointing from `other` to `self` (behind `self`'s facing when they share an x). */
183	function awayFrom(self: FighterState, other: FighterState): Facing {
184	  return self.x > other.x ? 1 : self.x < other.x ? -1 : self.facing === 1 ? -1 : 1;
185	}
186	
187	/** The move frame a fighter executes this frame, or 0 when it is not attacking. */
188	function currentMoveFrame(fighter: FighterState): number {
189	  return fighter.action === "attack" ? fighter.actionFrame + 1 : 0;
190	}
191	
192	function isActiveFrame(move: DuelMove, moveFrame: number): boolean {
193	  return moveFrame > move.timing.startup && moveFrame <= move.timing.startup + move.timing.active;
194	}
195	
196	/** Whether the fighter's strike hitbox is out on this frame, whether or not it reaches or already connected. */
197	function strikeActive(moveset: DuelMoveset, fighter: FighterState): boolean {
198	  if (fighter.action !== "attack" || fighter.moveId === null) return false;
199	  const move = findMove(moveset, fighter.moveId);
200	  return move.kind === "strike" && isActiveFrame(move, currentMoveFrame(fighter));
201	}
202	
203	function isAirborne(fighter: FighterState): boolean {
204	  return fighter.y > 0 || fighter.vy > 0 || fighter.action === "jump";
205	}
206	
207	/** A free or blocking fighter changes stance with this frame's input; anyone else keeps the one they had. */
208	function stanceOf(fighter: FighterState, input: FrameInput): Stance {
209	  if (isAirborne(fighter)) return "airborne";
210	  if (canAct(fighter) || fighter.action === "blockstun") return input.v === -1 ? "crouching" : "standing";
211	  return fighter.crouching ? "crouching" : "standing";
212	}
213	
214	function detect(moveset: DuelMoveset, fighters: Pair<FighterState>, attacker: PlayerIndex, input: Pair<FrameInput>): Contact | null {
215	  const att = fighters[attacker];
216	  if (att.action !== "attack" || att.moveId === null || att.moveHit) return null;
217	  const move = findMove(moveset, att.moveId);
218	  if (!isActiveFrame(move, currentMoveFrame(att))) return null;
219	  const defender = OTHER[attacker];
220	  const def = fighters[defender];
221	  const stance = stanceOf(def, input[defender]);
222	  const reaches = () =>
223	    overlaps(worldBox(move.hitbox, att.x, att.y, att.facing), worldBox(moveset.fighter.hurtboxes[stance], def.x, def.y, def.facing));
224	
225	  if (move.kind === "throw") {
226	    const throwable =
227	      stance !== "airborne" && !["hitstun", "blockstun", "thrown", "throw-break", "knockdown"].includes(def.action);
228	    return throwable && reaches() ? { kind: "grab", move, stance } : null;
229	  }
230	  if (def.action === "thrown" || def.action === "knockdown") return null;
231	  if (def.action === "attack" && def.moveId !== null && findMove(moveset, def.moveId).strikeInvulnerable >= currentMoveFrame(def)) {
232	    return null;
233	  }
234	  // Crouching avoids highs whether or not it guards.
235	  if (move.guard === "high" && stance === "crouching") return null;
236	  if (!reaches()) return null;
237	  const guarding =
238	    stance !== "airborne" &&
239	    (canAct(def) || def.action === "blockstun") &&
240	    input[defender].h === awayFrom(def, att) &&
241	    (stance === "standing" ? move.guard === "high" || move.guard === "mid" : move.guard === "low");
242	  return { kind: guarding ? "block" : "hit", move, stance };
243	}
244	
245	/** A thrown fighter escapes by pressing light and heavy (both within the buffer) while the window is open. */
246	function escapes(fighter: FighterState, input: FrameInput): boolean {
247	  return fighter.action === "thrown" && fighter.timer > 0 && input.buffer.light > 0 && input.buffer.heavy > 0;
248	}
249	
250	function scaledDamage(moveset: DuelMoveset, damage: number, comboHits: number): number {
251	  const scaling = moveset.rules.comboScaling;
252	  const percent = scaling[Math.min(comboHits, scaling.length - 1)]!;
253	  return divTrunc(damage * percent, 100);
254	}
255	
256	/** Starts a timed action lasting `frames` frames, the current one included. */
257	function startTimed(fighter: FighterState, action: FighterState["action"], frames: number): FighterState {
258	  return {
259	    ...fighter,
260	    action,
261	    actionFrame: 1,
262	    timer: Math.max(0, frames - 1),
263	    moveId: null,
264	    moveHit: false,
265	    vx: 0,
266	    vy: fighter.y > 0 ? Math.min(fighter.vy, 0) : 0,
267	    crouching: false,
268	  };
269	}
270	
271	function react(moveset: DuelMoveset, fighter: FighterState, contact: Contact, attacker: PlayerIndex): { fighter: FighterState; event: DuelEvent } {
272	  const { move, stance } = contact;
273	  const { rules } = moveset;
274	  const moveId = move.timing.id;
275	  const crouching = stance === "crouching";
276	  if (contact.kind === "grab") {
277	    // The escape window is the ten frames after the grab; presses from before it do not count.
278	    const held = startTimed(fighter, "thrown", rules.throwEscapeFrames + 1);
279	    return {
280	      fighter: { ...held, combo: 0, buffer: { ...held.buffer, light: 0, heavy: 0 } },
281	      event: { kind: "grab", attacker, moveId, damage: 0 },
282	    };
283	  }
284	  if (contact.kind === "block") {
285	    const cost = move.guardStaminaCost;
286	    if (cost > fighter.stamina) {
287	      const staggered = startTimed(fighter, "stagger", rules.guardBreakStaggerFrames);
288	      return {
289	        fighter: { ...staggered, combo: 0, stamina: Math.min(rules.maxStamina, rules.guardBreakStaminaRestore) },
290	        event: { kind: "guard-break", attacker, moveId, damage: 0 },
291	      };
292	    }
293	    return {
294	      fighter: { ...startTimed(fighter, "blockstun", move.blockstun), combo: 0, crouching, stamina: fighter.stamina - cost },
295	      event: { kind: "block", attacker, moveId, damage: 0 },
296	    };
297	  }
298	  // A fighter still in hitstun continues the combo; a free one starts a new one.
299	  const comboHits = fighter.action === "hitstun" && !canAct(fighter) ? fighter.combo : 0;
300	  const damage = scaledDamage(moveset, move.damage, comboHits);
301	  const combo = comboHits + 1;
302	  const capped = combo >= rules.comboCap;
303	  const struck = startTimed(fighter, capped ? "knockdown" : "hitstun", capped ? rules.forcedRecoveryFrames : move.hitstun);
304	  return {
305	    fighter: {
306	      ...struck,
307	      health: Math.max(0, fighter.health - damage),
308	      combo,
309	      crouching: capped ? false : crouching,
310	      vy: move.launch > 0 ? move.launch : struck.vy,
311	    },
312	    event: { kind: "hit", attacker, moveId, damage },
313	  };
314	}
315	
316	/** One more frame of an action the fighter cannot leave yet. */
317	function progress(moveset: DuelMoveset, fighter: FighterState): FighterState {
318	  const actionFrame = fighter.actionFrame + 1;
319	  const timer = Math.max(0, fighter.timer - 1);
320	  switch (fighter.action) {
321	    case "attack": {
322	      const move = findMove(moveset, fighter.moveId!);
323	      return { ...fighter, actionFrame, timer, vx: advance(move, actionFrame, fighter.facing) };
324	    }
325	    case "dash":
326	    case "backdash":
327	      return { ...fighter, actionFrame, timer };
328	    case "jump":
329	      return { ...fighter, actionFrame };
330	    default:
331	      return { ...fighter, actionFrame, timer, vx: 0 };
332	  }
333	}
334	
335	function advance(move: DuelMove, moveFrame: number, facing: Facing): number {
336	  return move.advance !== 0 && moveFrame <= move.timing.startup + move.timing.active ? move.advance * facing : 0;
337	}
338	
339	/** A free fighter turns to face the opponent and starts whatever its input asks for (§8's priorities). */
340	function choose(moveset: DuelMoveset, self: FighterState, opponent: FighterState, input: FrameInput): FighterState {
341	  const facing: Facing = opponent.x > self.x ? 1 : opponent.x < self.x ? -1 : self.facing;
342	  const { buffer, h, v } = input;
343	  const { commands, fighter: body, rules } = moveset;
344	  const base: FighterState = { ...self, facing, combo: 0, moveHit: false, moveId: null, crouching: false, vy: 0 };
345	  const consume = (...buttons: readonly (keyof InputBuffer)[]): InputBuffer =>
346	    ({ ...buffer, ...Object.fromEntries(buttons.map((button) => [button, 0])) }) as InputBuffer;
347	  const attack = (id: string, used: InputBuffer): FighterState => {
348	    const move = findMove(moveset, id);
349	    return {
350	      ...base,
351	      action: "attack",
352	      moveId: id,
353	      actionFrame: 1,
354	      timer: moveDuration(move) - 1,
355	      crouching: move.stance === "crouching",
356	      vx: advance(move, 1, facing),
357	      buffer: used,
358	    };
359	  };
360	  const forward = h === facing;
361	  const back = h === -facing;
362	
363	  if (buffer.light > 0 && buffer.heavy > 0) return attack(commands.throw, consume("light", "heavy"));
364	  if (buffer.special1 > 0) return attack(commands.special1, consume("special1"));
365	  if (buffer.special2 > 0) return attack(commands.special2, consume("special2"));
366	  if (buffer.heavy > 0) {
367	    return attack(v === -1 ? commands.downHeavy : forward ? commands.forwardHeavy : commands.heavy, consume("heavy"));
368	  }
369	  if (buffer.light > 0) return attack(v === -1 ? commands.downLight : commands.light, consume("light"));
370	  if (buffer.dash > 0 && self.stamina >= rules.dashStaminaCost) {
371	    const frames = back ? body.backdashFrames : body.dashFrames;
372	    return {
373	      ...base,
374	      action: back ? "backdash" : "dash",
375	      actionFrame: 1,
376	      timer: frames - 1,
377	      vx: back ? -facing * body.backdashSpeed : facing * body.dashSpeed,
378	      stamina: self.stamina - rules.dashStaminaCost,
379	      buffer: consume("dash"),
380	    };
381	  }
382	  /** A free action: its frame count carries on while the fighter keeps doing it. */
383	  const free = (action: "idle" | "walk" | "crouch" | "jump", vx: number): FighterState => ({
384	    ...base,
385	    action,
386	    actionFrame: self.action === action ? self.actionFrame + 1 : 1,
387	    timer: 0,
388	    vx,
389	  });
390	  if (v === 1) return { ...free("jump", h * body.jumpSpeedX), vy: body.jumpVelocity };
391	  if (v === -1) return { ...free("crouch", 0), crouching: true };
392	  if (h !== 0) return free("walk", forward ? facing * body.walkForwardSpeed : -facing * body.walkBackSpeed);
393	  return free("idle", 0);
394	}
395	
396	/** Velocity, gravity and landing for one fighter, plus this frame's pushback, kept inside the walls. */
397	function move(moveset: DuelMoveset, fighter: FighterState, shift: number): FighterState {
398	  const minX = moveset.fighter.pushbox.halfWidth;
399	  const maxX = moveset.arena.width - minX;
400	  const x = clampInt(fighter.x + shift + fighter.vx, minX, maxX);
401	  if (fighter.y === 0 && fighter.vy <= 0) return { ...fighter, x, vy: 0 };
402	  const y = fighter.y + fighter.vy;
403	  if (y > 0) return { ...fighter, x, y, vy: fighter.vy - moveset.fighter.gravity };
404	  const landed = { ...fighter, x, y: 0, vx: 0, vy: 0 };
405	  return fighter.action === "jump" ? { ...landed, action: "idle", actionFrame: 1 } : landed;
406	}
407	
408	/**
409	 * Pushes overlapping pushboxes apart, each fighter by half the overlap rounded up, so neither side is favoured; a
410	 * fighter against a wall passes its share to the other.
411	 */
412	function separate(moveset: DuelMoveset, fighters: Pair<FighterState>): Pair<FighterState> {
413	  const { halfWidth, height } = moveset.fighter.pushbox;
414	  const [a, b] = fighters;
415	  const dx = Math.abs(a.x - b.x);
416	  if (dx >= 2 * halfWidth || a.y >= b.y + height || b.y >= a.y + height) return fighters;
417	  const aLeft = a.x < b.x || (a.x === b.x && a.facing === 1);
418	  const [left, right] = aLeft ? [a, b] : [b, a];
419	  const half = divTrunc(2 * halfWidth - dx + 1, 2);
420	  const minX = halfWidth;
421	  const maxX = moveset.arena.width - halfWidth;
422	  let leftX = left.x - half;
423	  let rightX = right.x + half;
424	  if (leftX < minX) {
425	    rightX += minX - leftX;
426	    leftX = minX;
427	  }
428	  if (rightX > maxX) {
429	    leftX = Math.max(minX, leftX - (rightX - maxX));
430	    rightX = maxX;
431	  }
