     1	/**
     2	 * One player's duel input for one frame: a bit field of held directions and buttons (§8). Directions are absolute
     3	 * (left is towards x = 0), not relative to facing, and are kept as separate bits so that the step itself resolves
     4	 * left + right (and up + down) to neutral. Throw is light and heavy together; there is no separate throw bit.
     5	 */
     6	export const DUEL_INPUT = {
     7	  left: 1 << 0,
     8	  right: 1 << 1,
     9	  up: 1 << 2,
    10	  down: 1 << 3,
    11	  light: 1 << 4,
    12	  heavy: 1 << 5,
    13	  special1: 1 << 6,
    14	  special2: 1 << 7,
    15	  dash: 1 << 8,
    16	} as const;
    17	
    18	/** Every defined bit; a duel input is an integer in [0, DUEL_INPUT_MASK]. */
    19	export const DUEL_INPUT_MASK = 0x1ff;
    20	
    21	/** The buttons the input buffer remembers, in the order the step checks them. */
    22	export const DUEL_BUTTONS = ["light", "heavy", "special1", "special2", "dash"] as const;
    23	
    24	export type DuelButton = (typeof DUEL_BUTTONS)[number];
