     1	import { z } from "zod";
     2	import { formatIssues, type ValidationResult } from "../rules.js";
     3	import { DUEL_INPUT_MASK } from "./input.js";
     4	
     5	export const DUEL_INPUT_LOG_FORMAT = "pirate-sea-race/duel-input-log";
     6	
     7	/** One player's input bits for one frame. Unknown bits are refused, not masked. */
     8	export const duelInputSchema = z.int().min(0).max(DUEL_INPUT_MASK);
     9	
    10	/**
    11	 * A recorded duel, as JSON:
    12	 *
    13	 * ```json
    14	 * { "format": "pirate-sea-race/duel-input-log", "version": 1, "movesetVersion": "duelist-1",
    15	 *   "startFrame": 0, "inputs": [[0, 0], [2, 1], [2, 17]] }
    16	 * ```
    17	 *
    18	 * `inputs[i]` holds player one's and player two's input bits (`DUEL_INPUT`) for duel frame `startFrame + i + 1`,
    19	 * so a log that starts from a state at frame N replays from that state. `movesetVersion` must match the move data
    20	 * and the starting state.
    21	 */
    22	export const duelInputLogSchema = z.strictObject({
    23	  format: z.literal(DUEL_INPUT_LOG_FORMAT),
    24	  version: z.literal(1),
    25	  movesetVersion: z.string().min(1),
    26	  startFrame: z.int().nonnegative(),
    27	  inputs: z.array(z.tuple([duelInputSchema, duelInputSchema])),
    28	});
    29	
    30	export type DuelInputLog = z.infer<typeof duelInputLogSchema>;
    31	
    32	export function validateDuelInputLog(candidate: unknown): ValidationResult<DuelInputLog> {
    33	  const parsed = duelInputLogSchema.safeParse(candidate);
    34	  return parsed.success ? { ok: true, value: parsed.data } : { ok: false, issues: formatIssues(parsed.error) };
    35	}

