 27	/** A duel with the fighters at `x0` and `x1`, optionally changed, at `frame`. */
 28	function duel(x0: number, x1: number, patch0: Partial<FighterState> = {}, patch1: Partial<FighterState> = {}, frame = 0): DuelState {
 29	  const state = createDuelState(config, { x: [x0, x1] });
 30	  return { ...state, frame, fighters: [{ ...state.fighters[0], ...patch0 }, { ...state.fighters[1], ...patch1 }] };
 31	}
 32	
 33	/** Player two against the right wall (holding right is its guard), player one `dx` to its left. */
 34	function cornered(dx: number, patch0: Partial<FighterState> = {}, patch1: Partial<FighterState> = {}): DuelState {
 35	  return duel(RIGHT_WALL - dx, RIGHT_WALL, patch0, patch1);
 36	}
 37	
 38	function hold(frames: number, p1 = 0, p2 = 0): DuelInputs[] {
 39	  return Array.from({ length: frames }, () => [p1, p2] as const);
 40	}
 41	
 42	function script(...parts: DuelInputs[][]): DuelInputs[] {
 43	  return parts.flat();
 44	}
 45	
 46	/** Every state from the initial one; `trace[k]` is the state after k frames. */
 47	function run(state: DuelState, inputs: readonly DuelInputs[]): DuelState[] {
 48	  return traceDuel(config, state, inputs);
 49	}
 50	
 51	function events(trace: readonly DuelState[]) {
 52	  return trace.flatMap((state) => state.events.map((event) => ({ frame: state.frame, ...event })));
 53	}
 54	
 55	/** The first frame after `after` on which the fighter can start something. */
 56	function firstFreeFrame(trace: readonly DuelState[], index: 0 | 1, after: number): number {
 57	  for (let frame = after; frame < trace.length; frame++) if (canAct(trace[frame]!.fighters[index])) return frame + 1;
 58	  throw new Error("the fighter never became free");
 59	}
