  1	import { duelistMoveset, validateDuelInputLog } from "@pirate-sea-race/content/moves";
  2	import { describe, expect, it } from "vitest";
  3	import { canonicalize } from "../hash.js";
  4	import { nextInt } from "../random.js";
  5	import {
  6	  createDuelInputLog,
  7	  createDuelState,
  8	  defaultDuelConfig as config,
  9	  duelInput as I,
 10	  hashState,
 11	  mirrorDuelInput,
 12	  MOVESET_VERSION,
 13	  replayDuel,
 14	  restoreDuel,
 15	  sliceDuelInputLog,
 16	  snapshotDuel,
 17	  stepDuel,
 18	  traceDuel,
 19	  type DuelConfig,
 20	  type DuelEvent,
 21	  type DuelInputs,
 22	  type DuelState,
 23	  type FighterState,
 24	} from "./index.js";
 25	
 26	const FRAMES = config.moveset.rules.roundFrames;
 27	
 28	/** A seeded pseudo-random fight that lasts the round: mostly movement and guard, with occasional one-frame attacks. */
 29	function randomInputs(seed: number, frames: number): DuelInputs[] {
 30	  let rng = seed;
 31	  const draw = (bound: number) => {
 32	    const drawn = nextInt(rng, bound);
 33	    rng = drawn.state;
 34	    return drawn.value;
 35	  };
 36	  const held = [0, 0];
 37	  const left = [0, 0];
 38	  const inputs: DuelInputs[] = [];
 39	  for (let frame = 0; frame < frames; frame++) {
 40	    for (const player of [0, 1] as const) {
 41	      if (left[player] === 0) {
 42	        // Player one starts on the left, so its back is left; player two's is right.
 43	        const back = player === 0 ? I("left") : I("right");
 44	        const forward = player === 0 ? I("right") : I("left");
 45	        const moves = [0, back, back, back | I("down"), forward, forward, I("down"), I("up"), I("up") | forward, I("up") | back, I("dash"), back | I("dash"), I("left", "right")];
 46	        const attacks = [I("light"), I("heavy"), I("down", "heavy"), forward | I("heavy"), I("down", "light"), I("special1"), I("special2"), I("light", "heavy")];
