  1	import { describe, expect, it } from "vitest";
  2	import { baselineFrameBudgets } from "../frameBudgets.js";
  3	import {
  4	  DUEL_INPUT,
  5	  DUEL_INPUT_MASK,
  6	  duelistMoves,
  7	  duelistMoveset,
  8	  MOVESET_VERSION,
  9	  validateDuelInputLog,
 10	  validateDuelMove,
 11	  validateDuelMoveset,
 12	  type DuelMove,
 13	  type DuelMoveset,
 14	} from "./index.js";
 15	
 16	const byId = (id: string) => duelistMoves.find((move) => move.timing.id === id)!;
 17	const withMove = (id: string, change: (move: DuelMove) => unknown): unknown => ({
 18	  ...duelistMoveset,
 19	  moves: duelistMoveset.moves.map((move) => (move.timing.id === id ? change(move) : move)),
 20	});
 21	
 22	function issuesOf(candidate: unknown): string[] {
 23	  const result = validateDuelMoveset(candidate);
 24	  return result.ok ? [] : result.issues;
 25	}
 26	
 27	describe("Duelist move data", () => {
 28	  it("is valid and identified by MOVESET_VERSION", () => {
 29	    expect(validateDuelMoveset(duelistMoveset).ok).toBe(true);
 30	    expect(duelistMoveset.version).toBe(MOVESET_VERSION);
 31	  });
 32	
 33	  it("has the six normals and the two specials (§7, §9)", () => {
 34	    expect(duelistMoves.map((move) => move.timing.id)).toEqual([
 35	      "jab",
 36	      "heavy-mid",
 37	      "low-sweep",
 38	      "launcher",
 39	      "anti-air",
 40	      "throw",
 41	      "advancing-thrust",
 42	      "counter-slash",
 43	    ]);
 44	    expect(duelistMoveset.commands).toEqual({
 45	      light: "jab",
 46	      downLight: "anti-air",
 47	      heavy: "heavy-mid",
 48	      downHeavy: "low-sweep",
 49	      forwardHeavy: "launcher",
 50	      special1: "advancing-thrust",
 51	      special2: "counter-slash",
 52	      throw: "throw",
 53	    });
 54	  });
 55	
 56	  it("takes the jab, heavy mid, low sweep and throw timings from §8's baseline table itself", () => {
 57	    for (const id of ["jab", "heavy-mid", "low-sweep", "throw"]) {
 58	      expect(byId(id).timing).toBe(baselineFrameBudgets.find((row) => row.id === id));
 59	    }
 60	  });
 61	
 62	  it("keeps §7's damage: a 45 jab, 100-150 for committed heavies and specials", () => {
 63	    expect(byId("jab").damage).toBe(45);
 64	    for (const move of duelistMoves.filter((candidate) => candidate.category === "heavy" || candidate.category === "special")) {
 65	      expect(move.damage).toBeGreaterThanOrEqual(100);
 66	      expect(move.damage).toBeLessThanOrEqual(150);
 67	    }
 68	  });
 69	
 70	  it("charges §7's guard stamina: light 10, heavy 25, special 20", () => {
 71	    expect(duelistMoves.map((move) => [move.timing.id, move.guardStaminaCost])).toEqual([
 72	      ["jab", 10],
 73	      ["heavy-mid", 25],
 74	      ["low-sweep", 25],
 75	      ["launcher", 25],
 76	      ["anti-air", 10],
 77	      ["throw", 0],
 78	      ["advancing-thrust", 20],
 79	      ["counter-slash", 20],
 80	    ]);
 81	  });
 82	
 83	  it("keeps §7's round, stamina, combo and throw rules and §8's input buffer", () => {
 84	    expect(duelistMoveset.rules).toMatchObject({
 85	      roundFrames: 3600,
 86	      overtimeFrames: 600,
 87	      maxHealth: 1000,
 88	      maxStamina: 100,
 89	      dashStaminaCost: 20,
 90	      staminaRegenDelayFrames: 60,
 91	      staminaRegenIntervalFrames: 3,
 92	      guardBreakStaggerFrames: 30,
 93	      guardBreakStaminaRestore: 30,
 94	      comboScaling: [100, 80, 65, 50, 40],
 95	      comboCap: 5,
 96	      throwEscapeFrames: 10,
 97	      inputBufferFrames: 4,
 98	    });
 99	  });
100	
101	  it("makes the heavy's blocked spacing reachable by the jab", () => {
102	    const standing = duelistMoveset.fighter.hurtboxes.standing;
103	    const heavy = byId("heavy-mid");
104	    const jab = byId("jab");
105	    // Farthest origin distance at which the heavy still touches a standing hurtbox, plus its block pushback.
106	    const leftBehind = heavy.hitbox.x + heavy.hitbox.w - standing.x - 1 + heavy.blockPushback;
107	    expect(leftBehind).toBeLessThan(jab.hitbox.x + jab.hitbox.w - standing.x);
108	    expect([heavy.blockPushback, jab.hitbox.x + jab.hitbox.w]).toEqual([64, 1024]);
109	  });
110	});
111	
112	describe("move validator", () => {
113	  const jab = byId("jab");
114	
115	  it.each([
116	    ["zero startup", { ...jab, timing: { ...jab.timing, startup: 0 } }, "timing.startup"],
117	    ["negative startup", { ...jab, timing: { ...jab.timing, startup: -1 } }, "timing.startup"],
