 1	import { z } from "zod";
 2	import { formatIssues, type ValidationResult } from "./rules.js";
 3	
 4	/** How the attacker stands after the defender blocks (§8): a frame advantage, or one of the table's special cases. */
 5	export const onBlockSchema = z.discriminatedUnion("kind", [
 6	  /** Negative is minus: "Minus 12" is `{ kind: "frames", advantage: -12 }`. */
 7	  z.strictObject({ kind: z.literal("frames"), advantage: z.int() }),
 8	  z.strictObject({ kind: z.literal("spacing-dependent") }),
 9	  z.strictObject({ kind: z.literal("unguardable") }),
10	]);
11	
12	/**
13	 * One row of the baseline frame budgets (§8), in 60 Hz frames. `active` is `"projectile-life"` when the hit lives on
14	 * a projectile rather than the fighter.
15	 */
16	export const moveTimingSchema = z
17	  .strictObject({
18	    id: z.string().regex(/^[a-z][a-z0-9-]*$/),
19	    name: z.string().min(1),
20	    startup: z.int().positive(),
21	    active: z.union([z.int().positive(), z.literal("projectile-life")]),
22	    recovery: z.int().nonnegative(),
23	    onBlock: onBlockSchema,
24	  })
25	  .superRefine((move, ctx) => {
26	    // Advantage on block is blockstun minus the attacker's remaining active and recovery frames. Blockstun is never
27	    // negative, so the attacker can never be more minus than active + recovery.
28	    if (move.onBlock.kind === "frames" && typeof move.active === "number" && move.onBlock.advantage < -(move.active + move.recovery)) {
29	      ctx.addIssue({
30	        code: "custom",
31	        path: ["onBlock", "advantage"],
32	        message: `minus ${-move.onBlock.advantage} on block exceeds active + recovery (${move.active + move.recovery} frames)`,
33	      });
34	    }
35	  });
36	
37	export type MoveTiming = z.infer<typeof moveTimingSchema>;
38	
39	export const baselineFrameBudgets = [
40	  { id: "jab", name: "Jab", startup: 7, active: 3, recovery: 12, onBlock: { kind: "frames", advantage: -2 } },
41	  { id: "heavy-mid", name: "Heavy mid", startup: 18, active: 4, recovery: 24, onBlock: { kind: "frames", advantage: -12 } },
42	  { id: "low-sweep", name: "Low sweep", startup: 20, active: 3, recovery: 26, onBlock: { kind: "frames", advantage: -15 } },
43	  { id: "projectile-special", name: "Projectile special", startup: 22, active: "projectile-life", recovery: 30, onBlock: { kind: "spacing-dependent" } },
44	  { id: "throw", name: "Throw", startup: 12, active: 2, recovery: 24, onBlock: { kind: "unguardable" } },
45	] as const satisfies readonly MoveTiming[];
46	
47	export function validateMoveTiming(candidate: unknown): ValidationResult<MoveTiming> {
48	  const parsed = moveTimingSchema.safeParse(candidate);
49	  return parsed.success ? { ok: true, value: parsed.data } : { ok: false, issues: formatIssues(parsed.error) };
50	}
51	
52	/** Validates a whole table: every row, and no id used twice. */
53	export function validateFrameBudgets(candidate: unknown): ValidationResult<MoveTiming[]> {
54	  const parsed = z.array(moveTimingSchema).safeParse(candidate);
55	  if (!parsed.success) return { ok: false, issues: formatIssues(parsed.error) };
56	  const seen = new Set<string>();
57	  const issues: string[] = [];
58	  for (const move of parsed.data) {
59	    if (seen.has(move.id)) issues.push(`${move.id}: duplicate move id`);
60	    seen.add(move.id);
61	  }
62	  return issues.length > 0 ? { ok: false, issues } : { ok: true, value: parsed.data };
63	}

