import { createDuelState, defaultDuelConfig as config, duelInput as I, traceDuel, type DuelInputs } from "./packages/simulation/src/duel/index.ts";
const hold = (n: number, a = 0, b = 0): DuelInputs[] => Array.from({ length: n }, () => [a, b] as const);
const W = config.moveset.arena.width - 256;
for (const gap of [1, 2]) {
  const inputs = [...hold(1, I("light")), ...hold(gap - 1, I("light")), ...hold(1, I("light", "heavy")), ...hold(40)];
  const tr = traceDuel(config, createDuelState(config, { x: [W - 600, W] }), inputs);
  console.log("J then K after", gap, "frame(s):", tr[1]!.fighters[0].moveId, tr.flatMap(s => s.events.map(e => `${s.frame} ${e.kind} ${e.moveId}`)));
}
// whiffing strike facing away vs connecting throw: p1 does anti-air facing left (away), p2 throws from p1's right
const st = createDuelState(config, { x: [5000, 5600] });
const s0 = { ...st, fighters: [{ ...st.fighters[0], facing: -1 as const, action: "attack" as const, moveId: "jab", actionFrame: 11, timer: 11 }, st.fighters[1]] as const };
// jab active on move frames 8-10: set so that p1 jab (facing away) active when p2 throw active on frame 13
const s1 = { ...st, fighters: [{ ...st.fighters[0], facing: -1 as const }, st.fighters[1]] as const };
const tr2 = traceDuel(config, s1 as any, [...hold(1, 0, I("light", "heavy")), ...hold(5), ...hold(1, I("light"), 0), ...hold(30)]);
console.log("facing-away jab vs throw:", tr2[7]!.fighters[0].facing, tr2.flatMap(s => s.events.map(e => `${s.frame} ${e.kind} ${e.moveId}`)));
const tr3 = traceDuel(config, s1 as any, [...hold(1, 0, I("light", "heavy")), ...hold(40)]);
console.log("no jab:", tr3.flatMap(s => s.events.map(e => `${s.frame} ${e.kind} ${e.moveId}`)));
EOF
cd $S && /home/agentops/dev/project-B/node_modules/.bin/tsx --conditions=@pirate-sea-race/source t.ts

